// Types for data/schemata.json and data/cadences.json (generated by tools/build.py).
// Degrees use circled numerals in display strings: ①–⑦ = bass scale degrees; ①–⑦ in "melody" = upper-voice degrees.

export type Tab = 'schemata' | 'cadences';
export type Direction = 'ASC' | 'DSC' | 'ASC/DSC' | 'static' | 'mixed' | 'circular';
export type VerificationStatus = 'verified' | 'partly' | 'notes-only' | 'flagged';

export interface ContentFile {
  version: 1;
  tab: Tab;
  groups: Group[];
  patterns: Pattern[];
}

export interface Group {
  id: string;
  title: string;
  blurb: string;
  notesPages?: string; // pages in the handwritten notes
}

export interface Pattern {
  id: string;                 // stable slug, use in URLs (#id)
  tab: Tab;
  group: string;              // Group.id
  name: string;
  aka?: string[];
  kind: 'moto' | 'schema' | 'pedal' | 'combination' | 'cadence' | 'clausula' | 'definition' | 'nomenclature' | 'demo';
  direction?: Direction;
  bass?: string;              // human-readable bass degrees, e.g. "④–③–②–①"
  melody?: string;
  degrees?: string;           // clausulae
  modes?: ('major' | 'minor')[];
  textures?: number[];        // 2, 3, 4 parts
  meter?: string;
  function?: string[];
  form?: string;              // cadences: Simple | Compound | Double | Half …
  figures?: string;           // figured-bass summary as written in the notes
  summary: string;
  rules?: string[];           // HARD rules (render with a "Rule" badge)
  guidelines?: string[];      // SOFT rules / tips (render with a "Guideline" badge)
  examples?: Example[];
  variants?: Variant[];
  seeAlso?: string[];         // Pattern ids (may point to the other tab)
  nomenclature?: unknown;     // only on id "nomenclature" (cadences) – see BUILD_BRIEF §5.2
  conclusiveness?: string; rank?: number; cadenceWhenInBass?: string; // clausulae
  sources: Sources;
  verification: { status: VerificationStatus; checks: string[]; flags?: string[] };
}

export interface Variant {
  id: string;
  name: string;
  description: string;
  figures?: string;
  examples?: Example[];
  review?: string | boolean;  // true/string = content needs the owner's check before publishing
}

export interface Example {
  id: string;
  title: string;
  key: 'C' | 'a' | 'd' | 'G' | 'F' | 'e';   // upper case = major, lower = minor
  meter: string;
  beatUnit: 'half' | 'quarter';  // what 1.0 beat means for durations
  notation: string;              // mini-notation (source of truth, see BUILD_BRIEF §4)
  caption?: string;
  parts: number;                 // number of voices incl. bass
  cross?: boolean;               // voice crossing is intentional
  review?: string | boolean;
  realized: {
    voiceOrder: string;          // "top→bottom; last = bass"
    lengthBeats: number;
    voices: RealizedEvent[][];   // voices[0] = top … voices[n-1] = bass
  };
  checker?: { type: 'par5' | 'par8' | 'tie' | 'doubledLT'; severity: 'error' | 'info'; beat: number; voices: [number, number] | number | null; detail: string }[];
}

export interface RealizedEvent {
  t: number;        // onset in beats
  d: number;        // duration in beats
  rest?: true;
  pitch?: string;   // scientific pitch, e.g. "F#4", "Bb3"
  midi?: number;
  tie?: true;       // tied from the previous event (suspension / tied bass)
  fig?: string;     // the interval figure that produced this note, e.g. "7", "#6", "4+"
}

export interface Sources {
  notes?: string;      // handwritten notes + page
  hcp?: string;        // IJzerman, Harmony, Counterpoint, Partimento (OUP 2018) section
  fenaroli?: string;   // Fenaroli, Partimenti ossia basso numerato, Book III (Rules, 1775)
  web?: string[];      // essaysonmusic.com (Ewald Demeyere) pages
  other?: string;
}
